// PROTECTED: independently AI-reviewed draft. Never import into public practice.
// Human instructional/regulatory review and all approval gates remain outstanding.
export const FINAL_01_03 = [
  {"id":"LOC-F-T01-01","tests":"T01U4","unitCode":"T01U4","module":"module-01","prompt":"A vacancy occurs in a State Bar-appointed position on the Broker-Lawyer Committee before the term ends. Under the statutory vacancy rule, which entity fills the unexpired term?","choices":["The entity that made the original appointment.","The Commission, regardless of which entity originally appointed the member.","The governor, because the unexpired term is shorter than a full term.","The committee members, by selecting a replacement from the same professional group."],"correctChoice":0,"rationale":"Section 1101.253(b)–(c) addresses continued service and vacancies. The original appointing entity fills the unexpired term, rather than transferring the appointment to an unrelated participant.","source":"Texas Occupations Code Chapter 1101","section":"§ 1101.253(c)","sources":[{"url":"https://tcss.legis.texas.gov/resources/OC/htm/OC.1101.htm","reference":"Texas Occupations Code Chapter 1101, § 1101.253(c)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"New vacancy mechanism, unlike formative committee-role questions; replace irrelevant parties with plausible appointing authorities.","instructionEvidence":"module-01 T01U4; assigned §§1101.252–1101.254"},
  {"id":"LOC-F-T01-02","tests":"T01U4","unitCode":"T01U4","module":"module-01","prompt":"A draft standardized form expedites closings but intentionally omits safeguards for the principals. Which statutory requirement remains unsatisfied?","choices":["The forms must contain adequate safeguards protecting the principals.","Expediting transactions is sufficient even if safeguards are omitted.","Safeguards are required only for the license holders completing the form.","Protection of either principal is sufficient if the committee chooses one."],"correctChoice":0,"rationale":"Efficiency is not the only committee mandate. Section 1101.254(b) expressly requires adequate safeguards for transaction principals.","source":"Texas Occupations Code Chapter 1101","section":"§ 1101.254(b)","sources":[{"url":"https://tcss.legis.texas.gov/resources/OC/htm/OC.1101.htm","reference":"Texas Occupations Code Chapter 1101, § 1101.254(b)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain the statutory safeguards test, which is not the formative promulgation-versus-recommendation case.","instructionEvidence":"module-01 T01U4"},
  {"id":"LOC-F-T01-03","tests":"T01U6","unitCode":"T01U6","module":"module-01","prompt":"An independently owned business with $28 million in assets seeks property solely for business use. Applying the stated DTPA consumer definition, which threshold issue arises?","choices":["The business-consumer asset exclusion at $25 million or more.","A universal requirement that every consumer be an individual.","A rule excluding every lease regardless of assets.","A rule measuring only annual revenue rather than assets."],"correctChoice":0,"rationale":"Section 17.45(4) excludes a business consumer meeting the stated asset threshold and addresses ownership or control by a qualifying entity. The question supplies business use and $28 million in assets.","source":"Texas Business & Commerce Code Chapter 17","section":"§ 17.45(4), (10)","sources":[{"url":"https://tcss.legis.texas.gov/resources/BC/htm/BC.17.htm","reference":"Texas Business & Commerce Code Chapter 17, § 17.45(4), (10)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"RETAIN","reviewReason":"Asset exclusion is a new application of the expressly taught consumer definition; the three distractors are genuine definition errors.","instructionEvidence":"module-01 T01U6, consumer and business-consumer definitions"},
  {"id":"LOC-F-T01-04","tests":"T01U6","unitCode":"T01U6","module":"module-01","prompt":"A prospective tenant seeks residential leasing services but has not yet signed a lease. Which phrase in the DTPA definition explains why absence of a completed acquisition is not alone dispositive?","choices":["Seeks or acquires by purchase or lease.","Only a person who has completed the purchase or lease.","Only a person who pays this defendant directly for the services.","Only an individual who already occupies the acquired property."],"correctChoice":0,"rationale":"Consumer status can involve seeking covered goods or services, not only completing an acquisition. Other statutory conditions still must be satisfied; the absence of a signed lease alone does not settle status.","source":"Texas Business & Commerce Code Chapter 17","section":"§ 17.45(4)","sources":[{"url":"https://tcss.legis.texas.gov/resources/BC/htm/BC.17.htm","reference":"Texas Business & Commerce Code Chapter 17, § 17.45(4)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Seeking residential leasing services tests the statutory scope; alternatives now express plausible completion, privity, and occupancy errors.","instructionEvidence":"module-01 T01U6, seeks or acquires"},
  {"id":"LOC-F-T01-05","tests":"T01U6","unitCode":"T01U6","module":"module-01","prompt":"A claimant identifies an enumerated deceptive act but offers no evidence that it was relied on to the claimant’s detriment. Which element of the § 17.50(a)(1) route remains at issue?","choices":["Detrimental reliance on the enumerated act, along with the other required elements.","A separate showing of intent to deceive is always required for every §17.50(a)(1) claim.","Proof of any regulatory violation replaces reliance under this route.","Only a signed contract directly between claimant and defendant can supply the missing element."],"correctChoice":0,"rationale":"The laundry-list route includes reliance to the consumer’s detriment. Identifying an enumerated act does not eliminate the remaining claim requirements.","source":"Texas Business & Commerce Code Chapter 17","section":"§ 17.50(a)(1)","sources":[{"url":"https://tcss.legis.texas.gov/resources/BC/htm/BC.17.htm","reference":"Texas Business & Commerce Code Chapter 17, § 17.50(a)(1)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Missing reliance is a distinct element-identification task, not the practice square-footage accuracy case.","instructionEvidence":"module-01 T01U6, four doors into an action"},
  {"id":"LOC-F-T01-06","tests":"T01U6","unitCode":"T01U6","module":"module-01","prompt":"A consumer’s claimed loss consists of repair expense and mental anguish. Which classification correctly applies the statutory definition of economic damages?","choices":["Repair expense can be pecuniary loss; mental anguish is excluded from the economic-damages definition.","Repair expense and mental anguish are both economic damages because both arise from the transaction.","Repair expense is excluded, but mental anguish is economic loss whenever the claimant assigns it a dollar value.","Mental anguish is excluded from economic damages and therefore cannot be considered under any other DTPA remedy provision."],"correctChoice":0,"rationale":"Section 17.45(11) includes repair and replacement costs in pecuniary loss and excludes mental anguish from economic damages. Other remedy provisions must be analyzed separately.","source":"Texas Business & Commerce Code Chapter 17","section":"§ 17.45(11)","sources":[{"url":"https://tcss.legis.texas.gov/resources/BC/htm/BC.17.htm","reference":"Texas Business & Commerce Code Chapter 17, § 17.45(11)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain damage-category distinction; replace absurd definition with plausible confusion between classification and availability.","instructionEvidence":"module-01 T01U6; module-06 T06U9, economic damages and mental anguish"},
  {"id":"LOC-F-T01-07","tests":"T01U2","unitCode":"T01U2","module":"module-01","prompt":"A person receives $4,000 for brokerage activity while unlicensed. Under a statutory civil-penalty range of the amount received through three times that amount, what is the upper end for that single range?","choices":["$12,000.","$4,000.","$8,000.","$16,000."],"correctChoice":0,"rationale":"Three times $4,000 is $12,000. This calculation concerns the stated single statutory range; it does not combine separate claimants, penalties, or other remedies.","source":"Texas Occupations Code Chapter 1101","section":"§ 1101.753(a)","sources":[{"url":"https://tcss.legis.texas.gov/resources/OC/htm/OC.1101.htm","reference":"Texas Occupations Code Chapter 1101, § 1101.753(a)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"RETAIN","reviewReason":"The supplied statutory range leads to an independent arithmetic task; neither a formative computation nor the same taught dollar case was located.","instructionEvidence":"module-01 T01U2, unlicensed activity; supplied range"},
  {"id":"LOC-F-T01-08","tests":"T01U5","unitCode":"T01U5","module":"module-01","prompt":"A broker holds trust money under the parties’ written instructions. The bank returns the deposit check unpaid. The buyer says a replacement will arrive tomorrow and asks the broker to tell only the seller’s agent orally. Which immediate communication does §535.146 require?","choices":["Written notice to all parties that the trust-money check was dishonored.","Notice only if the replacement check also fails.","Oral notice to either brokerage, with written notice deferred until closing.","Written notice only to the buyer who wrote the check."],"correctChoice":0,"rationale":"The rule requires immediate written notice to all parties when a trust-money check is dishonored. A promised replacement does not suspend that notice duty.","source":"Texas Real Estate Commission rules","section":"§535.146(c)(8), dishonored trust-money check","sources":[{"url":"https://www.trec.texas.gov/agency-information/rules-and-laws/trec-rules","reference":"Texas Real Estate Commission rules, §535.146(c)(8), dishonored trust-money check"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats module-01 current-versus-old training form example. This substitutes a specific taught trust-custody event and required recipient/method.","instructionEvidence":"module-01 T01U5, Earnest money: Custody"},
  {"id":"LOC-F-T01-09","tests":"T01U3","unitCode":"T01U3","module":"module-01","prompt":"A principal is about to execute an instrument that must be acknowledged and filed of record. The principal has asked the agent only to coordinate the appointment, not for a legal opinion. Which affirmative step does §537.11(e) still require?","choices":["Advise the principal to consult an attorney before executing the instrument.","Recommend counsel only after the clerk rejects the instrument.","Give no attorney advisory unless the principal first alleges a defect.","Treat scheduling with a notary as satisfying the attorney-consultation advisory."],"correctChoice":0,"rationale":"The rule imposes an affirmative pre-execution attorney advisory for an instrument that must be acknowledged and filed of record. This does not require the agent to give legal advice or decide the instrument’s validity.","source":"Texas Real Estate Commission rules","section":"§537.11(e)","sources":[{"url":"https://www.trec.texas.gov/agency-information/rules-and-laws/trec-rules","reference":"Texas Real Estate Commission rules, §537.11(e)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original agreed-price field repeats formative T01U5-R agreed-deadline informational completion. New question tests the affirmative advisory trigger, not whether an agent may fill a blank.","instructionEvidence":"module-01 T01U3 and T01U5, affirmative advisory duties"},
  {"id":"LOC-F-T01-10","tests":"T01U1","unitCode":"T01U1","module":"module-01","prompt":"A file contains a buyer–seller purchase agreement, a buyer’s separate loan commitment, and an escrow receipt. The lender approves a smaller loan; the escrow holder acknowledges the receipt. Neither buyer nor seller agrees to a new price. Which record establishes a buyer–seller price amendment?","choices":["None of these later events establishes that the buyer and seller agreed to change their price.","The smaller loan commitment, because the lender controls the purchase price.","The escrow acknowledgment, because holding the deposit makes escrow a seller representative with price authority.","Both later documents together, because third-party approvals replace the parties’ assent."],"correctChoice":0,"rationale":"The lender and escrow holder have distinct roles. Their documents do not, on these facts, establish the principals’ agreement to a price change. This is document/party identification, not a legal conclusion about a disputed actual contract.","source":"TREC One to Four Family Residential Contract (Resale), 20-19","section":"Paragraphs 3, 18 and 22","sources":[{"url":"https://www.trec.texas.gov/forms/one-four-family-residential-contract-resale","reference":"TREC One to Four Family Residential Contract (Resale), 20-19, Paragraphs 3, 18 and 22"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats T01U1-Q/R duty-versus-election distinction. New task identifies which participants and records could establish a change to the bargain.","instructionEvidence":"module-01 T01U1, parties and document functions"},
  {"id":"LOC-F-T01-11","tests":"T01U6","unitCode":"T01U6","module":"module-01","prompt":"A defendant invokes the licensed-broker DTPA exemption, but the alleged conduct is a material factual misrepresentation not characterizable as advice, judgment, or opinion. What must be examined?","choices":["The express exceptions to the broker exemption.","The exemption is absolute whenever the defendant held an active real-estate license.","The exemption applies unless the consumer paid this broker directly.","The exemption necessarily applies whenever the representation appears inside an opinion paragraph."],"correctChoice":0,"rationale":"Section 17.49(i) contains specified exceptions. Licensure does not convert a material factual misrepresentation into protected advice or supply universal immunity.","source":"Texas Business & Commerce Code Chapter 17","section":"§ 17.49(i)(1)","sources":[{"url":"https://tcss.legis.texas.gov/resources/BC/htm/BC.17.htm","reference":"Texas Business & Commerce Code Chapter 17, § 17.49(i)(1)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain the specifically stated material-fact exception; distractors now test license status, privity, and substance versus label.","instructionEvidence":"module-01 T01U6, §17.49(i) carve-outs"},
  {"id":"LOC-F-T01-12","tests":"T01U5","unitCode":"T01U5","module":"module-01","prompt":"A client supplies a document but asks the license holder to conceal a deletion from the other party. Which feature of the request conflicts with the rule’s permitted-deletion framework?","choices":["The change is to be concealed rather than made conspicuous under the applicable conditions.","A principal’s specific instruction permits the agent to hide the deletion if both principals later sign.","A deletion is conspicuous whenever the resulting paragraph remains grammatical.","A separate oral explanation substitutes for clearly identifying the changed text."],"correctChoice":0,"rationale":"Permitted deletions are subject to the rule’s stated conditions, including conspicuous treatment. A principal’s request does not authorize hidden alteration of contractual language.","source":"Texas Real Estate Commission rules","section":"§ 537.11","sources":[{"url":"https://www.trec.texas.gov/agency-information/rules-and-laws/trec-rules","reference":"Texas Real Estate Commission rules, § 537.11"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"The final tests failure of conspicuousness; MC-T01 instead supplies compliant mechanics and tests whether they authorize legal advice. Different operative condition.","instructionEvidence":"module-01 T01U5; MC-T01"},
  {"id":"LOC-F-T02-01","tests":"T02U7","unitCode":"T02U7","module":"module-02","prompt":"A condominium declaration assigns use of a loading area to Units 1 and 2, but not the other eighteen units. The area lies outside every unit boundary. Under the §82.003 definitions, which classification fits this stated allocation?","choices":["A limited common element allocated to fewer than all units.","Part of Unit 1 alone because its owner uses the area most often.","An element available to every owner equally despite the stated allocation.","A separate cooperative share rather than an element of the condominium."],"correctChoice":0,"rationale":"Section 82.003(a)(16) defines a limited common element by allocation to one or more but fewer than all units. The scenario supplies the allocation and excludes placement inside a unit.","source":"Texas Property Code Chapter 82","section":"§82.003(a)(16)","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.82.htm","reference":"Texas Property Code Chapter 82, §82.003(a)(16)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original merely reverses formative T02U7-R’s direct-versus-corporate common-property definition. This uses a different statutory classification and a two-unit allocation.","instructionEvidence":"module-02 T02U7, common and limited common elements"},
  {"id":"LOC-F-T02-02","tests":"T02U7","unitCode":"T02U7","module":"module-02","prompt":"A unit description includes the condominium name, declaration recording data, county, and identifying unit number. Which statutory subject do those components address?","choices":["The sufficiency of a condominium unit’s legal description.","The amount of a condominium owner’s allocated voting percentage.","The boundaries of an ordinary subdivision lot without regard to any declaration.","The association’s permission for a proposed alteration to a common element."],"correctChoice":0,"rationale":"Section 82.054 identifies these components for a sufficient unit description and appurtenant interests. They should not be confused with financing or brokerage terms.","source":"Texas Property Code Chapter 82","section":"§ 82.054","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.82.htm","reference":"Texas Property Code Chapter 82, § 82.054"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"The stem supplies the listed components; identifying their legal-description function is answerable without memorizing an unassigned section. Pinpoint remains §82.054.","instructionEvidence":"module-02 T02U7, unit identifier and appurtenant interests"},
  {"id":"LOC-F-T02-03","tests":"T02U6","unitCode":"T02U6","module":"module-02","prompt":"The company agreement expressly makes an LLC manager-managed and names Morgan, who owns no membership interest, as its sole manager. The sale is an act of ordinary company business within the manager’s authority. What is the relevant governance distinction?","choices":["The designated manager can be the governing authority without personally owning a membership interest.","Only a member can be a manager or participate in the governing authority.","All members necessarily manage every act despite the manager-managed agreement.","The buyer becomes the governing authority once the purchase offer is delivered."],"correctChoice":0,"rationale":"Section 101.251 identifies the managers as the governing authority when the company agreement provides for manager management. The scenario establishes the appointment and ordinary-business scope; it does not ask the agent to infer authority from a business card.","source":"Texas Business Organizations Code Chapter 101","section":"§101.251(a)(1); supplied established manager appointment","sources":[{"url":"https://tcss.legis.texas.gov/resources/BO/htm/BO.101.htm","reference":"Texas Business Organizations Code Chapter 101, §101.251(a)(1); supplied established manager appointment"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats T02U6-Q’s membership-versus-specific-asset decision. This tests established management rather than missing authority evidence.","instructionEvidence":"module-02 T02U6, management structure and authority"},
  {"id":"LOC-F-T02-04","tests":"T02U3","unitCode":"T02U3","module":"module-02","prompt":"The parties expressly exclude a named chandelier through the authorized contract entry. Which evidence best addresses whether that item was intended to remain?","choices":["The actual agreed exclusion in the operative contract.","A generic photograph taken before negotiation.","The buyer’s uncommunicated assumption.","A moving company’s inventory created later."],"correctChoice":0,"rationale":"The explicit agreed treatment is the operative evidence of the parties’ bargain. Physical attachment and marketing appearance do not justify ignoring an agreed exclusion.","source":"TREC One to Four Family Residential Contract (Resale), 20-19","section":"Paragraph 2, property inclusions and exclusions","sources":[{"url":"https://www.trec.texas.gov/forms/one-four-family-residential-contract-resale","reference":"TREC One to Four Family Residential Contract (Resale), 20-19, Paragraph 2, property inclusions and exclusions"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"RETAIN","reviewReason":"A resolved, express chandelier exclusion differs from the practice’s unresolved inclusion dispute: the final asks which existing evidence controls, not how to create an agreement. All distractors are credible competing evidence types.","instructionEvidence":"module-02 T02U3; T02U3-Q"},
  {"id":"LOC-F-T02-05","tests":"T02U2","unitCode":"T02U2","module":"module-02","prompt":"For this ownership calculation, a seller owns a 60% undivided mineral interest in the tract. The agreed reservation expressly retains one-half of that seller-owned interest, not one-half of the entire tract’s mineral estate. What tract-wide percentage of mineral ownership remains for this seller to convey?","choices":["30%.","50%.","60%.","10%."],"correctChoice":0,"rationale":"One-half of the seller’s 60% interest is 30%; retaining that 30% leaves 30% to convey. The stated denominator eliminates the ambiguity that requires counsel in the teaching’s royalty-versus-mineral example. No conclusion is made about any other owner’s interest.","source":"TREC Addendum for Reservation of Oil, Gas, and Other Minerals, 44-3","section":"Form 44-3, Section B; supplied ownership and reservation fractions","sources":[{"url":"https://www.trec.texas.gov/sites/default/files/pdf-forms/44-3.pdf","reference":"TREC Addendum for Reservation of Oil, Gas, and Other Minerals, 44-3, Form 44-3, Section B; supplied ownership and reservation fractions"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats the prior-severance/actual-ownership practice branch. New task applies expressly established denominators and computes the conveyed share; it does not guess a fraction from a royalty check.","instructionEvidence":"module-02 T02U2, rights included; module-04 T04U6, distinguish ownership and reservation denominators"},
  {"id":"LOC-F-T02-06","tests":"T02U4","unitCode":"T02U4","module":"module-02","prompt":"A buyer cannot move a completed building to correct an inconvenient site. A separate buyer can sell an ownership interest but must negotiate a new transaction rather than substitute a different parcel automatically. Which pairing identifies the two physical characteristics being applied?","choices":["Immobility in the first file; uniqueness/noninterchangeability in the second.","Uniqueness in the first file; physical mobility in the second.","Indestructibility of improvements in the first file; automatic fungibility in the second.","Liquidity in the first file; identical location attributes in the second."],"correctChoice":0,"rationale":"Immobility concerns location; uniqueness concerns parcels not being automatically interchangeable. The paired classification requires separating two characteristics, not merely recognizing that equal acreage does not prove equal access.","source":"Texas Real Estate Commission rules","section":"§531.4; supplied hypothetical application of physical characteristics","sources":[{"url":"https://www.trec.texas.gov/agency-information/rules-and-laws/trec-rules","reference":"Texas Real Estate Commission rules, §531.4; supplied hypothetical application of physical characteristics"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats formative T02U4’s same-sized-parcel substitution/access comparison. New two-file task discriminates immobility from uniqueness.","instructionEvidence":"module-02 T02U4, physical characteristics"},
  {"id":"LOC-F-T02-07","tests":"T02U5","unitCode":"T02U5","module":"module-02","prompt":"One owner holds an undivided share in a tract. The buyer wants a physically separate corner instead of that undivided share. What difference must be recognized?","choices":["An undivided ownership interest is not itself a conveyance of a specifically partitioned corner.","The undivided percentage itself supplies the surveyed boundaries of the desired corner.","The co-owner’s occupancy of that corner proves an exclusive partition without another instrument.","A deed of the undivided share necessarily conveys every other owner’s rights in the chosen corner."],"correctChoice":0,"rationale":"The interest owned and the physical parcel proposed for conveyance are different questions. Appropriate title, survey, and legal work is needed to establish the intended transaction.","source":"Texas Property Code Chapter 5","section":"§§ 5.001 and 5.021","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.5.htm","reference":"Texas Property Code Chapter 5, §§ 5.001 and 5.021"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Keep the fractional-versus-spatial interest test: it differs from the formative problem of one co-owner attempting to convey all owners’ shares.","instructionEvidence":"module-02 T02U5, undivided means no particular corner"},
  {"id":"LOC-F-T02-08","tests":"T02U8","unitCode":"T02U8","module":"module-02","prompt":"An association adopts a new dedicatory instrument authorizing an assessment but never files it in the county real-property records. The association says posting the instrument on its member portal is equivalent. Which statutory issue does §202.006 identify?","choices":["The required filing has not been established; the statute conditions the instrument’s effect and collection of an authorized regular assessment on filing.","Portal posting always replaces county filing for a dedicatory instrument.","County filing is required only after the first regular assessment is collected.","A buyer’s lender approval supplies the filing required of the association."],"correctChoice":0,"rationale":"Section 202.006(a)–(c) requires filing in the relevant county records, states when a dedicatory instrument has effect, and bars collection of a regular assessment under an unfiled authorizing instrument. Portal publication is a different event.","source":"Texas Property Code Chapter 202","section":"Property Code §202.006(a)–(c)","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.202.htm#202.006","reference":"§202.006(a)–(c)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats formative T02U8-R’s public-permit/private-restriction branch. New question tests the filing prerequisite, which is expressly taught in T02U8.","instructionEvidence":"module-02 T02U8, Where private restrictions live"},
  {"id":"LOC-F-T02-09","tests":"T02U1","unitCode":"T02U1","module":"module-02","prompt":"An owner’s deed, a tenant’s lease, and a utility’s easement concern the same tract. An analyst is preparing a list of interests and places all three in a column labelled ownership of the entire fee. Which corrected set of labels preserves their different functions?","choices":["Owner’s estate; tenant’s possessory leasehold; utility’s defined use right.","Three competing claims to exclusive fee ownership of the entire tract.","Owner’s estate; tenant’s debt lien; utility’s residential lease.","Owner’s mortgage; tenant’s easement; utility’s unrestricted possession."],"correctChoice":0,"rationale":"The documents describe different interests, not three identical fee claims. This is a three-way classification from supplied instruments, not a promise that transfer extinguishes a particular lease or easement.","source":"TREC One to Four Family Residential Contract (Resale), 20-19","section":"Paragraphs 6 and 10; supplied instrument classifications","sources":[{"url":"https://www.trec.texas.gov/forms/one-four-family-residential-contract-resale","reference":"TREC One to Four Family Residential Contract (Resale), 20-19, Paragraphs 6 and 10; supplied instrument classifications"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats the practice conclusion that sale does not erase tenant/easement rights. Replacement instead requires correct positive classification of three interests, including the two nonfee categories.","instructionEvidence":"module-02 T02U1; module-04 T04U1"},
  {"id":"LOC-F-T02-10","tests":"T02U3","unitCode":"T02U3","module":"module-02","prompt":"A seller-owned attached light is expressly excluded. The signed contract separately requires the seller to repair damage caused by removing excluded property. The seller removes the light and leaves damaged wiring. Which status follows from those supplied terms and facts?","choices":["The exclusion permitted removal, but the separate removal-damage repair obligation remains unperformed.","Exclusion of the light also deleted the separate damage-repair obligation.","The buyer’s wish to keep the light automatically restores it as an inclusion.","Permission to remove the light automatically permits the seller to substitute an unagreed credit for the required repair."],"correctChoice":0,"rationale":"Exclusion and the obligation addressing removal damage are distinct. The accepted exclusion answers whether the item stays; it does not establish performance of the separate removal-damage duty.","source":"TREC One to Four Family Residential Contract (Resale), 20-19","section":"Paragraph 2D","sources":[{"url":"https://www.trec.texas.gov/forms/one-four-family-residential-contract-resale","reference":"TREC One to Four Family Residential Contract (Resale), 20-19, Paragraph 2D"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats the taught leased-solar third-party ownership case. New question tests the continuing physical-result obligation after a valid exclusion, not third-party title.","instructionEvidence":"module-02 T02U3, physical result of an exclusion","integrationReview":"Root converted question-shaped alternatives to definite status statements, removing possible multiple questions worth investigating."},
  {"id":"LOC-F-T02-11","tests":"T02U6","unitCode":"T02U6","module":"module-02","prompt":"A company has two authorized signers, but one signs the contract in the company’s name and the other signs only as a witness. The file identifies the company as the property owner. Which distinction should the reviewer preserve?","choices":["Authority to sign and the capacity in which a person actually signed are separate; a witness signature is not automatically a second execution for the company.","Every signature by an authorized person necessarily exercises all of that person’s authority.","The witness becomes the individual seller because the company owns the land.","Two signatures establish a transfer of the company’s membership interests regardless of the instrument."],"correctChoice":0,"rationale":"Establish the actual party and signing capacity as well as authority. The facts do not permit treating a witness signature as another exercise of company authority merely because the witness could have signed in a different role.","source":"Texas Business Organizations Code Chapter 101","section":"§101.254; supplied signature capacities","sources":[{"url":"https://tcss.legis.texas.gov/resources/BO/htm/BO.101.htm","reference":"Texas Business Organizations Code Chapter 101, §101.254; supplied signature capacities"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats the course’s adult-capacity-versus-LLC-authority example. New case supplies authority and tests actual signature capacity, not a missing authority document.","instructionEvidence":"module-02 T02U6, human signers and evidence of the capacity in which they act"},
  {"id":"LOC-F-T02-12","tests":"T02U7","unitCode":"T02U7","module":"module-02","prompt":"A condominium unit owner proposes buying an additional unit. Why should the declaration and allocated interests be reviewed rather than assuming each unit carries identical rights?","choices":["The declaration allocates common-element interests, expenses, votes, and other defined rights.","The listing price alone reallocates common interests and votes each time a unit sells.","Physical equality of units necessarily overrides unequal allocations in the declaration.","Acquiring a second unit automatically gives its owner control of every common element."],"correctChoice":0,"rationale":"Section 82.003 defines allocated interests and § 82.055 requires their allocation in the declaration. Price and physical appearance do not replace those governing documents.","source":"Texas Property Code Chapter 82","section":"§§ 82.003(a)(2) and 82.055(8)","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.82.htm","reference":"Texas Property Code Chapter 82, §§ 82.003(a)(2) and 82.055(8)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain declaration allocation question, distinct from determining whether an ownership regime is a condominium.","instructionEvidence":"module-02 T02U7, allocated interests"},
  {"id":"LOC-F-T03-01","tests":"T03U1","unitCode":"T03U1","module":"module-03","prompt":"Counsel reviewing negotiations reports that the parties have not established an agreed property description or selection method and asks the agent to obtain instructions rather than choose a parcel. Which status accurately preserves that supplied finding?","choices":["Property identification remains unresolved; obtain the parties’ instructions and appropriate documentation before reporting a complete bargain.","The agent may select the parcel with the highest asking price and report it as the parties’ agreement.","The buyer’s uncommunicated preference supplies the missing agreed selection method.","A stated closing date permits the agent to mark property identification complete without further instructions."],"correctChoice":0,"rationale":"The question supplies counsel’s finding rather than asking the license holder to decide a disputed legal definiteness issue. The agent must preserve that finding accurately and cannot manufacture the parties’ missing instructions or draft a legal solution.","source":"Texas Real Estate Commission rules","section":"§535.156; §537.11(b)(2), (3) and (5); supplied counsel finding","sources":[{"url":"https://www.trec.texas.gov/agency-information/rules-and-laws/trec-rules","reference":"Texas Real Estate Commission rules, §535.156; §537.11(b)(2), (3) and (5); supplied counsel finding"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original source did not precisely support the asserted property-description doctrine. Replacement removes that implied doctrine, supplies counsel’s conclusion, and tests accurate status and role boundaries.","instructionEvidence":"module-03 T03U1, identify unresolved terms without supplying private intent; module-01 legal-advice boundary"},
  {"id":"LOC-F-T03-02","tests":"T03U2","unitCode":"T03U2","module":"module-03","prompt":"A residential buyer broker first performs buyer brokerage services and only afterward obtains the buyer’s signed compensation memorandum. Assume counsel concludes that the later memorandum satisfies §1101.806(c) for the proposed collection action. Which separate question remains?","choices":["Whether the broker timely entered the written buyer agreement required before the services under §1101.563.","Whether satisfying the later commission-writing condition automatically establishes timely earlier practice compliance.","Whether a signed compensation memorandum necessarily proves the buyer never received brokerage services.","Whether §1101.806(c) abolishes every other written-agreement requirement for residential buyers."],"correctChoice":0,"rationale":"A sufficient signed memorandum for a commission action and a required agreement before buyer brokerage activity serve different purposes and have different timing. The supplied counsel determination answers only the first inquiry.","source":"Texas Occupations Code Chapter 1101","section":"§§1101.563(b) and 1101.806(c)","sources":[{"url":"https://tcss.legis.texas.gov/resources/OC/htm/OC.1101.htm","reference":"Texas Occupations Code Chapter 1101, §§1101.563(b) and 1101.806(c)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original duplicates the owner-accepted-work/no-writing worked case and has multiple correct answers under “prevents assuming.” Replacement supplies an enforceable writing and asks about the separate earlier practice duty.","instructionEvidence":"module-03 T03U2, three separate writing rules; module-05 required-writing source exercise"},
  {"id":"LOC-F-T03-03","tests":"T03U3","unitCode":"T03U3","module":"module-03","prompt":"Two offers concern locating a survey monument. Offer A requests a promise to conduct a search in exchange for a promised fee. Offer B promises a fee only for actually locating and reporting the monument and requests no return promise. Which acceptance distinction fits the stated offers?","choices":["A seeks a return promise; B seeks the specified performance.","Both seek only completed performance because both concern a service.","Both seek only a return promise because money is offered.","A seeks completed conveyance of land; B seeks a signed purchase agreement."],"correctChoice":0,"rationale":"Classification depends on the response the offer requests, not the subject being a service or the compensation being money. The two supplied offers deliberately use different acceptance structures.","source":"Supreme Court of Texas, Vanegas v. American Energy Services, No. 07-0520","section":"Opinion pages 5–6; annual compilation pages 315–316","sources":[{"url":"https://www.txcourts.gov/media/819887/OpinionsFY2010.pdf#page=311","reference":"Supreme Court of Texas, Vanegas v. American Energy Services, No. 07-0520, Opinion pages 5–6; annual compilation pages 315–316"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original is a tautological definition with unrelated-signature distractor. Replacement requires comparison of two complete offers; no taught reward or employment-bonus fact pattern is reused.","instructionEvidence":"module-03 T03U3, requested performance versus promises"},
  {"id":"LOC-F-T03-04","tests":"T03U4","unitCode":"T03U4","module":"module-03","prompt":"An oral lease is made today, starts today, and ends exactly one year from today. Considering only §26.01(b)(5), with no extension term, which statement is accurate?","choices":["This stated one-year term is not longer than one year, so that particular category does not itself establish the writing barrier.","The category applies to every lease lasting one year or longer.","Monthly rent payments make any lease term exempt, including a five-year lease.","Absence of this category guarantees enforceability under every other law and fact."],"correctChoice":0,"rationale":"Section 26.01(b)(5) says longer than one year. The conclusion is limited to that category and the specified exact term; it is not an enforceability guarantee or a ruling about other requirements.","source":"Texas Business & Commerce Code Chapter 26","section":"§26.01(b)(5)","sources":[{"url":"https://tcss.legis.texas.gov/resources/BC/htm/BC.26.htm","reference":"Texas Business & Commerce Code Chapter 26, §26.01(b)(5)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats formative oral-land-sale writing-versus-voidness classification. New task tests the statutory boundary and a deliberately limited conclusion, not an absent signature on a covered two-year lease.","instructionEvidence":"module-03 T03U2/U4, separate writing and enforceability inquiries"},
  {"id":"LOC-F-T03-05","tests":"T03U5","unitCode":"T03U5","module":"module-03","prompt":"A buyer paid an inspector for a completed inspection under one agreement. Under a separate purchase agreement, the buyer validly terminated before closing. Which conclusion avoids merging performance across the two contracts?","choices":["Performance of the inspection service and termination of the sale must each be evaluated under its own agreement.","Termination of the sale necessarily means the completed inspection service was never performed.","Payment of the inspector necessarily performs the buyer’s purchase-price obligation to the seller.","The inspector’s completed work necessarily obligates the buyer to close the terminated sale."],"correctChoice":0,"rationale":"The service agreement and the buyer-seller transaction involve separate promises. Completion of an inspection does not supply payment or conveyance under the resale contract, and valid sale termination does not unperform the separate service.","source":"TREC One to Four Family Residential Contract (Resale), 20-19","section":"Paragraphs 5, 7 and 9","sources":[{"url":"https://www.trec.texas.gov/forms/one-four-family-residential-contract-resale","reference":"TREC One to Four Family Residential Contract (Resale), 20-19, Paragraphs 5, 7 and 9"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"RETAIN","reviewReason":"Retain after strict review: the completed independent inspection-service agreement and terminated sale are not the practice’s partially performed, still-active sale. It tests separate contracts and the effect of termination, not merely signatures versus closing. No identical taught case located.","instructionEvidence":"module-03 T03U5; module-05 T05U4 service-agreement distinction"},
  {"id":"LOC-F-T03-06","tests":"T03U1","unitCode":"T03U1","module":"module-03","prompt":"A buyer writes that the proposed price is acceptable but expressly says the seller’s new possession term is rejected. The agent wants to describe the entire counterproposal as accepted because consideration is adequate. Which element still needs resolution?","choices":["Assent to the same complete proposed bargain, including possession.","Whether a sufficient price substitutes for assent to all disputed material terms.","Whether the agent can select either possession term because money was offered.","Whether acceptance of one term necessarily accepts every other term in the counterproposal."],"correctChoice":0,"rationale":"Adequate consideration and assent are separate formation inquiries. The buyer has expressly rejected a term, so the price response does not establish acceptance of the whole counterproposal.","source":"Supreme Court of Texas, Chalker Energy Partners III v. Le Norman Operating, No. 18-0352","section":"Opinion pages 7–13, objective agreement and formation context","sources":[{"url":"https://www.txcourts.gov/media/1445957/180352.pdf","reference":"Supreme Court of Texas, Chalker Energy Partners III v. Le Norman Operating, No. 18-0352, Opinion pages 7–13, objective agreement and formation context"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original duplicates deposit-versus-promises consideration teaching. Replacement makes consideration undisputed and requires identifying a different unresolved element; it is not the worked seller’s price counteroffer without any buyer response.","instructionEvidence":"module-03 T03U1, separate formation elements"},
  {"id":"LOC-F-T03-07","tests":"T03U2","unitCode":"T03U2","module":"module-03","prompt":"Parties agreed to use electronic records. A system records an authentic electronic signature, but the dispute concerns what the signer’s act meant in the surrounding agreement and circumstances. Which UETA distinction applies?","choices":["Attribution of the act and determination of its legal effect are separate inquiries.","Once an act is attributed, its legal effect is fixed by the software’s label regardless of context.","Agreement to use electronic records means attribution evidence is never relevant.","Only a paper copy can be considered when deciding the effect of an electronic act."],"correctChoice":0,"rationale":"Section 322.009(a) addresses attribution; subsection (b) addresses effect from context and surrounding circumstances, including the parties’ agreement and applicable law. Genuine attribution does not make the software label conclusive.","source":"Texas Business & Commerce Code Chapter 322","section":"§322.009(a)–(b)","sources":[{"url":"https://tcss.legis.texas.gov/resources/BC/htm/BC.322.htm","reference":"Texas Business & Commerce Code Chapter 322, §322.009(a)–(b)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original tests missing terms, already stated in formative T03U2-R and duplicated by final T03-01. Replacement assumes authenticity and asks the distinct effect inquiry.","instructionEvidence":"module-03 T03U2, required §§322.005/.007/.009 reading"},
  {"id":"LOC-F-T03-08","tests":"T03U4","unitCode":"T03U4","module":"module-03","prompt":"Counsel identifies an agreement as voidable at one party’s election, and that party has not exercised the available election. The agent labels the file already rescinded and discards upcoming performance dates. What is the conceptual error?","choices":["A power to avoid and a completed act of avoidance are different; the status and outstanding obligations require the actual election and legal advice.","Every voidable agreement is necessarily nonexistent from the moment of signature.","Only a fully performed agreement can ever be voidable.","The agent’s status label itself exercises the party’s legal election."],"correctChoice":0,"rationale":"The scenario supplies counsel’s classification instead of asking the agent to decide whether pressure constitutes duress. The lesson is to distinguish an available legal power from proof it was exercised and its effect.","source":"Texas Real Estate Commission rules","section":"§537.11(b)(2)–(3); supplied counsel determination","sources":[{"url":"https://www.trec.texas.gov/agency-information/rules-and-laws/trec-rules","reference":"Texas Real Estate Commission rules, §537.11(b)(2)–(3); supplied counsel determination"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original ordinary-pressure allegation is an abstract repeat of the practice allegation-not-rescission decision with a source that does not establish duress doctrine. Replacement assumes the classification and tests the unexercised election, without adding a new legal doctrine.","instructionEvidence":"module-03 T03U4, voidable versus actual rescission and meanings of cancel"},
  {"id":"LOC-F-T03-09","tests":"T03U3","unitCode":"T03U3","module":"module-03","prompt":"An option agreement says the holder has no duty to buy before exercise but must keep site-study information confidential immediately. The holder declines to exercise. Which classification avoids treating a purchase election as the absence of every present promise?","choices":["The purchase remains elective, while the expressly assumed confidentiality promise must be analyzed separately under its terms.","Declining to buy proves the holder could never have owed any contractual duty.","The confidentiality promise itself obligates the holder to buy.","Every document containing an option is wholly unenforceable until a deed is recorded."],"correctChoice":0,"rationale":"An option can preserve an election about the underlying purchase while imposing other stated obligations. The question supplies the independent confidentiality promise and does not ask whether an unexercised option conveys possession.","source":"Supreme Court of Texas, North Shore Energy v. Harkins, No. 14-0552","section":"Opinion page 12, option and underlying contract distinction; supplied confidentiality term","sources":[{"url":"https://www.txcourts.gov/media/1436267/140552.pdf","reference":"Supreme Court of Texas, North Shore Energy v. Harkins, No. 14-0552, Opinion page 12, option and underlying contract distinction; supplied confidentiality term"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original directly repeats the taught entry-option versus exit-option sentence. Replacement analyzes an independent present promise while purchase remains elective; no option-exercise notice or study-expenditure substitute case is reused.","instructionEvidence":"module-03 T03U3, option election and other present duties"},
  {"id":"LOC-F-T03-10","tests":"T03U5","unitCode":"T03U5","module":"module-03","prompt":"A five-acre tract will be used only for the purchaser’s commercial inventory storage, not as anyone’s residence. Deed delivery is deferred for several years. Which stipulated fact defeats an assumption that this transaction satisfies §5.062(a)’s residential-use requirement?","choices":["Its exclusive nonresidential use, rather than use as the purchaser’s or a qualifying relative’s residence.","Deferral beyond 180 days, because longer deferral itself excludes every transaction from Subchapter D.","The existence of future performance, because that means no executory contract can exist.","The tract’s five-acre area, because every tract of that size is automatically residential under subsection (a)(1)."],"correctChoice":0,"rationale":"Section 5.062(a) limits this scope inquiry to specified residential use. Deferred performance alone is not that use. The five-acre fact also avoids the one-acre-or-less residential presumption; no broader conclusion about other law is made.","source":"Texas Property Code Chapter 5","section":"§5.062(a), including subsection (a)(1)","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.5.htm","reference":"Texas Property Code Chapter 5, §5.062(a), including subsection (a)(1)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original 120-day deed-delivery exclusion repeats the module-08 six-week exclusion branch. New question holds lengthy deferral constant and changes the legally operative scope issue to established nonresidential use.","instructionEvidence":"module-03 T03U5, specialized statutory scope; module-05 T05U13 and module-08 T08U5 residential-use teaching"},
  {"id":"LOC-F-T03-11","tests":"T03U1","unitCode":"T03U1","module":"module-03","prompt":"Two parties agree that their negotiations will become binding only after both sign and deliver a specified definitive document. They sign it, but both expressly continue to hold their signed copies without delivery. Which part of their stated formation condition remains unestablished?","choices":["Delivery of the specified signed definitive document.","Any price discussion, because signatures cannot evidence any agreed terms.","Payment of the entire purchase price, although their condition does not require it.","Recording of the document, although their stated condition does not require recording."],"correctChoice":0,"rationale":"The supplied formation condition has two acts: signing and delivery. Proof of one does not supply the other. The question does not ask students to apply an untaught ambiguity standard or declare a real dispute resolved.","source":"Supreme Court of Texas, Chalker Energy Partners III v. Le Norman Operating, No. 18-0352","section":"Opinion pages 7–13, express definitive-agreement condition","sources":[{"url":"https://www.txcourts.gov/media/1445957/180352.pdf","reference":"Supreme Court of Texas, Chalker Energy Partners III v. Le Norman Operating, No. 18-0352, Opinion pages 7–13, express definitive-agreement condition"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original tests North Shore ambiguity doctrine not expressly taught in T03U1 or its assigned pinpoint. New case isolates delivery after signatures, rather than the practice’s price email before any definitive document exists.","instructionEvidence":"module-03 T03U1, express formation conditions"},
  {"id":"LOC-F-T03-12","tests":"T03U4","unitCode":"T03U4","module":"module-03","prompt":"A court has held one waiver invalid. For this hypothetical, the operative order expressly leaves the parties’ remaining purchase duties in force. Which file status is supported by that supplied ruling?","choices":["Remove reliance on the invalid waiver while continuing to track the remaining duties identified by the order.","Mark the entire purchase rescinded merely because one provision is invalid.","Continue to enforce the waiver because both parties originally signed it.","Treat the court’s order as permission for the agent to replace the waiver with a new remedy clause."],"correctChoice":0,"rationale":"The result follows the stated court order, not an invented universal severability rule. A clause-level ruling must not be expanded beyond its stated effect, and it does not authorize broker drafting.","source":"Texas Real Estate Commission rules","section":"§537.11(b); supplied hypothetical court order","sources":[{"url":"https://www.trec.texas.gov/agency-information/rules-and-laws/trec-rules","reference":"Texas Real Estate Commission rules, §537.11(b); supplied hypothetical court order"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original asks an abstract severability question while citing only a brokerage rule. Replacement supplies the legal determination and asks accurate administration of that limited result.","instructionEvidence":"module-03 T03U4, challenged clause versus whole agreement"},
];
